insert into public.products (id, slug, name, short_description, description, price, discount_percent, image, category_id, brand_id, type_id, stock_quantity, rating, rating_count, featured, specs, sort_order) values
  ('p-001', 'lululemon-align-legging', 'Lululemon Align High-Rise Legging 25"', 'Buttery-soft, weightless feel for yoga and everyday wear.', 'The legging people buy in every colour. Made from buttery-soft Nulu fabric that feels weightless, with a high rise that stays put through every pose, and a hidden waistband pocket for a card or key.', 145000, null, 'images/products/lululemon-align-legging.svg', 'sportswear', 'lululemon', 'leggings', 20, 4.9, 412, true, '[{"label":"Fabric","value":"Nulu (nylon/elastane)"},{"label":"Rise","value":"High-rise, 25\" inseam"},{"label":"Sizes","value":"XS – XL"},{"label":"Care","value":"Machine wash cold, hang to dry"}]'::jsonb, 0),
  ('p-002', 'lululemon-energy-bra', 'Lululemon Energy Bra', 'Medium support with a strappy back for training and runs.', 'A medium-support favourite for gym sessions and runs. Sweat-wicking fabric, removable cups and a strappy back that moves with you.', 78000, 5, 'images/products/lululemon-energy-bra.svg', 'sportswear', 'lululemon', 'sports-bras', 25, 4.7, 238, false, '[{"label":"Support","value":"Medium (B–D cups)"},{"label":"Fabric","value":"Luxtreme, sweat-wicking"},{"label":"Sizes","value":"XS – XL"},{"label":"Care","value":"Machine wash cold"}]'::jsonb, 1),
  ('p-003', 'lululemon-define-jacket', 'Lululemon Define Jacket', 'Sculpting, figure-hugging jacket with thumbholes.', 'A fitted jacket that looks as good at brunch as it does after class. Smooth, four-way stretch fabric, thumbholes and zipped side pockets.', 165000, 10, 'images/products/lululemon-define-jacket.svg', 'sportswear', 'lululemon', 'outerwear', 8, 4.8, 190, false, '[{"label":"Fabric","value":"Luon, four-way stretch"},{"label":"Fit","value":"Hugs the body, hip length"},{"label":"Sizes","value":"XS – XL"},{"label":"Care","value":"Machine wash cold"}]'::jsonb, 2),
  ('p-004', 'lululemon-the-mat-5mm', 'Lululemon The Mat 5mm', 'Grippy, cushioned yoga mat that soaks up sweat.', 'A sweat-resistant top layer that keeps its grip in hot flows, on a natural rubber base for cushioning on hard floors.', 120000, null, 'images/products/lululemon-the-mat-5mm.svg', 'equipment', 'lululemon', 'yoga', 0, 4.8, 305, false, '[{"label":"Thickness","value":"5 mm"},{"label":"Size","value":"180 × 66 cm"},{"label":"Material","value":"Polyurethane top, natural rubber base"},{"label":"Weight","value":"2.4 kg"}]'::jsonb, 3),
  ('p-005', 'lululemon-everywhere-belt-bag', 'Lululemon Everywhere Belt Bag', 'Hands-free essentials bag, worn on the hip or cross-body.', 'Keep your phone, cards and keys close on runs, at the gym or out and about. Water-repellent fabric and an adjustable strap.', 58000, null, 'images/products/lululemon-everywhere-belt-bag.svg', 'equipment', 'lululemon', 'bags', 3, 4.8, 520, false, '[{"label":"Capacity","value":"1 litre"},{"label":"Fabric","value":"Water-repellent nylon"},{"label":"Strap","value":"Adjustable, wear 3 ways"}]'::jsonb, 4),
  ('p-006', 'alo-airlift-legging', 'Alo Yoga Airlift High-Waist Legging', 'Sleek, sculpting legging with a smoothing high waist.', 'Alo’s signature Airlift fabric has a smooth, glossy finish that sculpts and lifts, with a high waistband that won’t roll down.', 160000, null, 'images/products/alo-airlift-legging.svg', 'sportswear', 'alo', 'leggings', 12, 4.7, 276, false, '[{"label":"Fabric","value":"Airlift (nylon/spandex)"},{"label":"Rise","value":"High-waist, 7/8 length"},{"label":"Sizes","value":"XS – L"},{"label":"Care","value":"Machine wash cold, lay flat to dry"}]'::jsonb, 5),
  ('p-007', 'alo-airlift-intrigue-bra', 'Alo Yoga Airlift Intrigue Bra', 'Light-support bra with a sculpted, criss-cross back.', 'A light-support bra designed to be seen, with a sculpted criss-cross back and the same smooth Airlift fabric as the leggings.', 92000, 15, 'images/products/alo-airlift-intrigue-bra.svg', 'sportswear', 'alo', 'sports-bras', 10, 4.6, 144, false, '[{"label":"Support","value":"Light"},{"label":"Fabric","value":"Airlift (nylon/spandex)"},{"label":"Sizes","value":"XS – L"}]'::jsonb, 6),
  ('p-008', 'alo-accolade-hoodie', 'Alo Yoga Accolade Hoodie', 'Heavyweight, relaxed-fit hoodie for after the session.', 'A thick, brushed-fleece hoodie with a relaxed fit and dropped shoulders — the one you’ll live in on rest days.', 190000, null, 'images/products/alo-accolade-hoodie.svg', 'sportswear', 'alo', 'outerwear', 6, 4.8, 98, false, '[{"label":"Fabric","value":"Brushed cotton-blend fleece"},{"label":"Fit","value":"Relaxed, unisex"},{"label":"Sizes","value":"XS – XL"}]'::jsonb, 7),
  ('p-009', 'alo-warrior-mat', 'Alo Yoga Warrior Mat', 'Extra-grippy, heavyweight mat for serious practice.', 'A dense, non-slip mat with alignment-friendly grip, built for daily practice. Wipes clean in seconds.', 175000, null, 'images/products/alo-warrior-mat.svg', 'equipment', 'alo', 'yoga', 4, 4.9, 210, false, '[{"label":"Thickness","value":"6 mm"},{"label":"Size","value":"188 × 66 cm"},{"label":"Material","value":"PU top, natural rubber base"},{"label":"Weight","value":"3.2 kg"}]'::jsonb, 8),
  ('p-010', 'nike-pegasus-41', 'Nike Pegasus 41 Running Shoes', 'Responsive everyday running shoe with ReactX foam.', 'A reliable daily trainer for road runs, treadmill sessions and everything in between, with springy ReactX foam and a breathable engineered mesh upper.', 185000, null, 'images/products/nike-pegasus-41.svg', 'sportswear', 'nike', 'footwear', 14, 4.7, 388, true, '[{"label":"Best for","value":"Road running, daily miles"},{"label":"Drop","value":"10 mm"},{"label":"Sizes","value":"EU 36 – 46"}]'::jsonb, 9),
  ('p-011', 'nike-dri-fit-tee', 'Nike Dri-FIT Training Tee', 'Lightweight, sweat-wicking tee for hard sessions.', 'Dri-FIT fabric moves sweat away from your skin so you stay dry and comfortable, with a relaxed cut that’s easy to move in.', 42000, null, 'images/products/nike-dri-fit-tee.svg', 'sportswear', 'nike', 'tops', 40, 4.5, 455, false, '[{"label":"Fabric","value":"Dri-FIT polyester"},{"label":"Fit","value":"Standard"},{"label":"Sizes","value":"S – XXL"}]'::jsonb, 10),
  ('p-012', 'nike-swoosh-bra', 'Nike Swoosh Medium-Support Bra', 'Comfortable everyday sports bra with removable pads.', 'A comfortable, supportive bra for training, cycling and everyday wear, with soft one-piece padding you can remove.', 48000, 10, 'images/products/nike-swoosh-bra.svg', 'sportswear', 'nike', 'sports-bras', 30, 4.6, 512, false, '[{"label":"Support","value":"Medium"},{"label":"Fabric","value":"Dri-FIT"},{"label":"Sizes","value":"XS – XL"}]'::jsonb, 11),
  ('p-013', 'nike-brasilia-duffel', 'Nike Brasilia Training Duffel', 'Roomy gym bag with a separate shoe compartment.', 'Fits everything for the gym and the office after, with a vented shoe compartment, a water-resistant base and a padded shoulder strap.', 65000, null, 'images/products/nike-brasilia-duffel.svg', 'equipment', 'nike', 'bags', 15, 4.6, 260, false, '[{"label":"Capacity","value":"41 litres"},{"label":"Pockets","value":"Shoe compartment, zipped front pocket"},{"label":"Material","value":"Polyester, water-resistant base"}]'::jsonb, 12),
  ('p-035', 'nike-metcon-9', 'Nike Metcon 9 Training Shoes', 'Stable, flat training shoe for lifting and HIIT.', 'A stable base for squats and deadlifts with enough cushioning for short runs and jumps — built for mixed gym sessions.', 175000, null, 'images/products/nike-metcon-9.svg', 'sportswear', 'nike', 'footwear', 0, 4.7, 174, false, '[{"label":"Best for","value":"Lifting, HIIT, cross-training"},{"label":"Drop","value":"4 mm"},{"label":"Sizes","value":"EU 36 – 46"}]'::jsonb, 13),
  ('p-014', 'on-cloudmonster', 'On Cloudmonster Running Shoes', 'Maximum cushioning with On’s signature CloudTec pods.', 'Big, bold cushioning for long runs. Oversized CloudTec pods soften every landing, and the rocker shape rolls you forward into the next step.', 260000, null, 'images/products/on-cloudmonster.svg', 'sportswear', 'on', 'footwear', 7, 4.8, 203, false, '[{"label":"Best for","value":"Long runs, recovery runs"},{"label":"Drop","value":"6 mm"},{"label":"Sizes","value":"EU 36 – 46"}]'::jsonb, 14),
  ('p-015', 'on-performance-long-t', 'On Performance Long-T', 'Lightweight long-sleeve running top with thumbholes.', 'A soft, quick-drying long-sleeve for early runs and air-conditioned gyms, with thumbholes and reflective details.', 95000, null, 'images/products/on-performance-long-t.svg', 'sportswear', 'on', 'tops', 5, 4.6, 61, false, '[{"label":"Fabric","value":"Recycled polyester, quick-dry"},{"label":"Fit","value":"Slim"},{"label":"Sizes","value":"XS – XL"}]'::jsonb, 15),
  ('p-016', 'on-cloud-6', 'On Cloud 6 Training Shoes', 'Light, all-day shoe for the gym and the city.', 'A light, everyday shoe that slips on easily and stays comfortable from morning workouts to evening plans.', 210000, 8, 'images/products/on-cloud-6.svg', 'sportswear', 'on', 'footwear', 9, 4.6, 140, false, '[{"label":"Best for","value":"Walking, light training, everyday"},{"label":"Weight","value":"About 230 g"},{"label":"Sizes","value":"EU 36 – 46"}]'::jsonb, 16),
  ('p-017', 'technogym-kettlebell-12kg', 'Technogym Kettlebell 12kg', 'Beautifully finished kettlebell with a smooth, wide handle.', 'Italian-designed kettlebell with a balanced shape for swings, cleans and squats, and a smooth finish that’s kind to your hands.', 180000, null, 'images/products/technogym-kettlebell-12kg.svg', 'equipment', 'technogym', 'weights', 6, 4.8, 47, false, '[{"label":"Weight","value":"12 kg"},{"label":"Material","value":"Cast iron, soft-touch coating"}]'::jsonb, 17),
  ('p-018', 'technogym-benchmark-dumbbells', 'Technogym Benchmark Dumbbells 10kg (pair)', 'Premium pair of dumbbells for a home gym that looks the part.', 'Solid, ergonomic dumbbells with a knurled grip and an elegant finish — made to sit beautifully in a home gym.', 420000, null, 'images/products/technogym-benchmark-dumbbells.svg', 'equipment', 'technogym', 'weights', 2, 4.9, 22, false, '[{"label":"Weight","value":"2 × 10 kg"},{"label":"Grip","value":"Knurled steel handle"}]'::jsonb, 18),
  ('p-019', 'technogym-resistance-bands', 'Technogym Resistance Band Kit', 'Three resistance levels for strength and mobility work.', 'Light, medium and heavy bands for warm-ups, glute work, mobility and travel workouts, in a compact carry pouch.', 75000, null, 'images/products/technogym-resistance-bands.svg', 'equipment', 'technogym', 'training', 18, 4.5, 66, false, '[{"label":"In the box","value":"3 bands (light, medium, heavy) + pouch"},{"label":"Material","value":"Latex-free elastic"}]'::jsonb, 19),
  ('p-020', 'technogym-exercise-mat', 'Technogym Exercise Mat', 'Thick, cushioned mat for floor work and stretching.', 'A thicker, cushioned mat for core work, pilates and stretching, with carry handles so it rolls up neatly.', 95000, null, 'images/products/technogym-exercise-mat.svg', 'equipment', 'technogym', 'yoga', 10, 4.6, 39, false, '[{"label":"Thickness","value":"8 mm"},{"label":"Size","value":"183 × 61 cm"}]'::jsonb, 20),
  ('p-021', 'theragun-pro-plus', 'Theragun PRO Plus', 'Professional-grade percussive massage gun with heat.', 'Therabody’s most advanced massage gun, with an adjustable arm, quiet motor and heated attachment for deep post-workout recovery.', 850000, null, 'images/products/theragun-pro-plus.svg', 'equipment', 'therabody', 'recovery', 3, 4.8, 88, true, '[{"label":"Speeds","value":"5 (1,750 – 2,400 per minute)"},{"label":"Battery","value":"About 150 minutes"},{"label":"Attachments","value":"6, including heat"},{"label":"Warranty","value":"12 months"}]'::jsonb, 21),
  ('p-022', 'theragun-mini', 'Theragun Mini', 'Pocket-size massage gun for recovery on the go.', 'Compact and quiet, with three speeds — small enough for your gym bag, strong enough for tight calves and shoulders.', 280000, 10, 'images/products/theragun-mini.svg', 'equipment', 'therabody', 'recovery', 11, 4.7, 302, false, '[{"label":"Speeds","value":"3"},{"label":"Battery","value":"About 150 minutes"},{"label":"Weight","value":"0.45 kg"},{"label":"Warranty","value":"12 months"}]'::jsonb, 22),
  ('p-023', 'therabody-waveroller', 'Therabody WaveRoller', 'Vibrating foam roller with a wave-textured surface.', 'A foam roller with five vibration settings and a wave-shaped surface to loosen up legs, back and glutes after training.', 165000, null, 'images/products/therabody-waveroller.svg', 'equipment', 'therabody', 'recovery', 0, 4.5, 54, false, '[{"label":"Vibration settings","value":"5"},{"label":"Battery","value":"About 3 hours"},{"label":"Length","value":"30 cm"}]'::jsonb, 23),
  ('p-024', 'momentous-grass-fed-whey', 'Momentous Essential Grass-Fed Whey (24 servings)', 'Clean, grass-fed whey protein. Vanilla.', 'A simple, high-quality whey protein from grass-fed cows, third-party tested, that mixes smoothly into water or milk.', 98000, null, 'images/products/momentous-grass-fed-whey.svg', 'supplements', 'momentous', 'protein', 25, 4.7, 196, true, '[{"label":"Servings","value":"24"},{"label":"Protein per serving","value":"About 20 g"},{"label":"Flavour","value":"Vanilla"},{"label":"Please note","value":"Food supplement. Not a substitute for a varied diet. Speak to a doctor first if pregnant, nursing or taking medication."}]'::jsonb, 24),
  ('p-025', 'momentous-creatine', 'Momentous Creatine Monohydrate (90 servings)', 'Unflavoured creatine monohydrate, 5 g a day.', 'Pure creatine monohydrate with no flavour, so it disappears into water, coffee or a shake. Third-party tested.', 52000, 10, 'images/products/momentous-creatine.svg', 'supplements', 'momentous', 'performance', 30, 4.8, 241, false, '[{"label":"Servings","value":"90"},{"label":"Serving size","value":"5 g"},{"label":"Flavour","value":"Unflavoured"},{"label":"Please note","value":"Food supplement. Not a substitute for a varied diet. Speak to a doctor first if pregnant, nursing or taking medication."}]'::jsonb, 25),
  ('p-026', 'momentous-sleep', 'Momentous Sleep', 'Evening blend with magnesium, apigenin and L-theanine.', 'A caffeine-free evening blend of magnesium, apigenin and L-theanine to take as part of your wind-down routine.', 68000, null, 'images/products/momentous-sleep.svg', 'supplements', 'momentous', 'wellness', 50, 4.4, 112, false, '[{"label":"Servings","value":"30"},{"label":"Form","value":"Capsules"},{"label":"Please note","value":"Food supplement. Not a substitute for a varied diet. Speak to a doctor first if pregnant, nursing or taking medication."}]'::jsonb, 26),
  ('p-027', 'heiress-smart-jump-rope', 'Heiress Smart Jump Rope', 'Weighted handles with a built-in jump counter.', 'Smooth ball-bearing rope with weighted gold-tone handles and a built-in counter for your skips and calories.', 18500, null, 'images/products/heiress-smart-jump-rope.svg', 'equipment', 'heiress', 'training', 60, 4.5, 133, false, '[{"label":"Length","value":"Adjustable, up to 3 m"},{"label":"Counter","value":"Skips, time and calories"}]'::jsonb, 27),
  ('p-028', 'heiress-sculpt-seamless-set', 'Heiress Sculpt Seamless Set', 'Matching seamless sports bra and high-waist legging.', 'Our signature two-piece: a supportive seamless bra and sculpting high-waist leggings with contour detailing, in a soft matte finish.', 85000, 12, 'images/products/heiress-sculpt-seamless-set.svg', 'sportswear', 'heiress', 'leggings', 16, 4.7, 158, true, '[{"label":"In the set","value":"Sports bra + legging"},{"label":"Fabric","value":"Seamless knit nylon/elastane"},{"label":"Sizes","value":"XS – XL"}]'::jsonb, 28),
  ('p-029', 'heiress-gold-grip-dumbbells', 'Heiress Gold Grip Dumbbells 5kg (pair)', 'Soft-touch hex dumbbells with gold-tone handles.', 'Non-roll hexagonal dumbbells with a soft-touch coating and gold-tone handles — as good-looking as they are useful.', 65000, null, 'images/products/heiress-gold-grip-dumbbells.svg', 'equipment', 'heiress', 'weights', 20, 4.6, 87, false, '[{"label":"Weight","value":"2 × 5 kg"},{"label":"Shape","value":"Hexagonal, won’t roll"}]'::jsonb, 29),
  ('p-030', 'heiress-ankle-weights', 'Heiress Ankle Weights 1kg (pair)', 'Adjustable ankle and wrist weights for pilates and toning.', 'Soft, adjustable weights that fasten around ankles or wrists to add a little extra to pilates, walks and glute work.', 28000, null, 'images/products/heiress-ankle-weights.svg', 'equipment', 'heiress', 'training', 25, 4.4, 76, false, '[{"label":"Weight","value":"2 × 1 kg"},{"label":"Fastening","value":"Adjustable strap"}]'::jsonb, 30),
  ('p-031', 'heiress-insulated-bottle', 'Heiress Insulated Bottle 1L', 'Keeps water ice-cold for 24 hours.', 'A double-walled steel bottle that keeps drinks cold all day in the Lagos heat, with a leak-proof lid and carry loop.', 22000, null, 'images/products/heiress-insulated-bottle.svg', 'equipment', 'heiress', 'bags', 40, 4.7, 201, false, '[{"label":"Capacity","value":"1 litre"},{"label":"Keeps cold","value":"Up to 24 hours"},{"label":"Material","value":"Stainless steel, BPA-free lid"}]'::jsonb, 31),
  ('p-032', 'heiress-plant-protein', 'Heiress Plant Protein (30 servings)', 'Pea and rice protein blend. Chocolate.', 'A smooth plant-based protein blend of pea and brown rice, dairy-free, in a rich chocolate flavour.', 45000, null, 'images/products/heiress-plant-protein.svg', 'supplements', 'heiress', 'protein', 22, 4.4, 94, false, '[{"label":"Servings","value":"30"},{"label":"Protein per serving","value":"About 20 g"},{"label":"Flavour","value":"Chocolate"},{"label":"Please note","value":"Food supplement. Not a substitute for a varied diet. Speak to a doctor first if pregnant, nursing or taking medication."}]'::jsonb, 32),
  ('p-033', 'heiress-daily-multivitamin', 'Heiress Daily Multivitamin (60 tablets)', 'Everyday vitamins and minerals for active women.', 'A once-a-day multivitamin with vitamins and minerals including iron, vitamin D and B vitamins, to support a balanced, active lifestyle.', 19500, 10, 'images/products/heiress-daily-multivitamin.svg', 'supplements', 'heiress', 'wellness', 35, 4.5, 118, false, '[{"label":"Tablets","value":"60 (two-month supply)"},{"label":"Dose","value":"1 tablet a day with food"},{"label":"Please note","value":"Food supplement. Not a substitute for a varied diet. Speak to a doctor first if pregnant, nursing or taking medication."}]'::jsonb, 33),
  ('p-034', 'heiress-electrolyte-sticks', 'Heiress Electrolyte Sticks (20 pack)', 'Sugar-free hydration sticks. Citrus.', 'Sugar-free electrolyte sticks with sodium, potassium and magnesium to mix into water before or after a sweaty session.', 15000, null, 'images/products/heiress-electrolyte-sticks.svg', 'supplements', 'heiress', 'performance', 45, 4.6, 143, false, '[{"label":"In the pack","value":"20 sticks"},{"label":"Flavour","value":"Citrus"},{"label":"Please note","value":"Food supplement. Not a substitute for a varied diet. Speak to a doctor first if pregnant, nursing or taking medication."}]'::jsonb, 34)
